"""public/assets/manifest.json -- regenerated by SCANNING the output folder at the end of every run.

No incremental merging: several builders may run `npm run assets` concurrently for different parts, and
each run rewrites the manifest from what is on disk (atomic temp + rename), so it can never be corrupted
or lose another run's parts.

  {
    "version": 1,
    "stages":  { "<stage id>": ["<part>", ...] },   a part is listed iff stages/<id>/<part>.json exists
    "cars":    ["<CarName>", ...],                  cars/<CarName>/ holds at least one <part>.json
    "carParts": { "<CarName>": ["<part>", ...] },
    "global":  ["<part>", ...],                     global/<part>.json
    "audio":   true | false,                        global/audio.json exists
    "textures": <number of tex/*.rtex files>
  }
Mirror: src/core/assets.ts (AssetManifest, ASSET_MANIFEST_VERSION).
"""
import hashlib
import json
import os

import archive as A
import stages as S
import textures as T

MANIFEST_VERSION = 1


def _parts_in(folder):
    """Part names = `<part>.json` files. Part names never contain '.', so a part's extra json files
    (`track.lod.json`, legal Output names) and temp files (`x.json.tmp.<pid>.<rand>`) are not parts."""
    if not os.path.isdir(folder):
        return []
    return sorted(f[:-5] for f in os.listdir(folder)
                  if f.endswith('.json') and '.' not in f[:-5] and os.path.isfile(os.path.join(folder, f)))


def scan(out_root):
    order = {sid: i for i, sid in enumerate(S.ported_order())}
    stages = {}
    sd = os.path.join(out_root, 'stages')
    if os.path.isdir(sd):
        for sid in sorted(os.listdir(sd), key=lambda s: (order.get(s, 1e9), s)):
            parts = _parts_in(os.path.join(sd, sid))
            if parts:
                stages[sid] = parts
    car_parts = {}
    cd = os.path.join(out_root, 'cars')
    if os.path.isdir(cd):
        for name in sorted(os.listdir(cd)):
            parts = _parts_in(os.path.join(cd, name))
            if parts:
                car_parts[name] = parts
    glob = _parts_in(os.path.join(out_root, 'global'))
    td = os.path.join(out_root, 'tex')
    ntex = sum(1 for f in os.listdir(td) if f.endswith('.rtex')) if os.path.isdir(td) else 0
    return {'version': MANIFEST_VERSION, 'stages': stages, 'cars': sorted(car_parts), 'carParts': car_parts,
            'global': glob, 'audio': 'audio' in glob, 'textures': ntex}


def write(out_root):
    """Scan + write under an inter-process lock: concurrent runs serialise here, so the run that finishes
    last always writes a scan taken after every run's files were complete (never a stale one)."""
    key = hashlib.sha1(os.path.abspath(out_root).encode('utf-8')).hexdigest()[:12]
    with A._Lock(os.path.join(A.CACHE_ROOT, 'locks', 'manifest-%s.lock' % key)):
        m = scan(out_root)
        T.atomic_write(os.path.join(out_root, 'manifest.json'), json.dumps(m, indent=1).encode('utf-8'))
    return m
